const results = [];

function extractEmail(value) {
  const text = String(value || "").trim();

  const match = text.match(/<([^>]+)>/);
  if (match) {
    return match[1].trim().toLowerCase();
  }

  const match2 = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  if (match2) {
    return match2[0].trim().toLowerCase();
  }

  return "";
}

for (const item of $input.all()) {

  const data = item.json;

  //----------------------------------------
  // 基础信息
  //----------------------------------------

  const rowId = data.id;

  const gmailMessageId =
    String(data.gmail_message_id || "");

  const gmailThreadId =
    String(data.gmail_thread_id || data.threadId || "");

  const lastMessageId =
    String(data.email_last_message_id || "");

  const snippet =
    String(data.snippet || "").trim();

  const text =
    snippet.toLowerCase();

  const customerEmail =
    String(
      data.email ||
      data.customer_email ||
      ""
    ).toLowerCase();

  const fromEmail =
    extractEmail(data.From);

  //----------------------------------------
  // 是否新邮件
  //----------------------------------------

  const isNewMessage =
    gmailMessageId !== "" &&
    gmailMessageId !== lastMessageId;

  //----------------------------------------
  // 当前状态
  //----------------------------------------

  let conversationStatus =
    data.email_conversation_status ||
    "waiting_reply";

  let deliveryStatus =
    data.email_outreach_status ||
    "sent";

  let failureReason =
    data.email_failure_reason ||
    null;

  let replyCount =
    Number(data.email_reply_count || 0);

  let lastReplyContent =
    data.email_last_reply_content ||
    null;

  let lastReplyAt =
    data.email_last_reply_at ||
    null;

  let conversationHistory =
    data.email_conversation_history ||
    "";

  const messageTime =
    data.internalDate
      ? new Date(Number(data.internalDate)).toISOString()
      : new Date().toISOString();

  //----------------------------------------
  // Bounce 判断
  //----------------------------------------

  const isBounce =
    data.is_bounce === true ||

    text.includes("address not found") ||
    text.includes("user unknown") ||
    text.includes("no such user") ||
    text.includes("recipient address rejected") ||
    text.includes("mailbox unavailable") ||

    text.includes("message wasn't delivered") ||
    text.includes("delivery failed") ||
    text.includes("delivery status notification") ||
    text.includes("undelivered mail") ||
    text.includes("returned mail") ||

    text.includes("domain not found") ||
    text.includes("host not found") ||
    text.includes("couldn't be found");

  //----------------------------------------
  // 是否客户回复
  //----------------------------------------

  const isCustomerReply =
    fromEmail &&
    customerEmail &&
    fromEmail === customerEmail &&
    !isBounce;

  //----------------------------------------
  // Bounce
  //----------------------------------------

  if (isBounce) {

    deliveryStatus = "failed";

    failureReason = snippet;

    // 保存退信历史
    if (conversationHistory.trim() !== "") {

      conversationHistory +=
`\n\n-------------------------
${messageTime}
-------------------------
${snippet}`;

    } else {

      conversationHistory = snippet;

    }

    if (

      text.includes("address not found") ||
      text.includes("user unknown") ||
      text.includes("no such user") ||
      text.includes("recipient address rejected") ||
      text.includes("mailbox unavailable")

    ) {

      conversationStatus = "invalid_email";

    }

    else if (

      text.includes("domain not found") ||
      text.includes("host not found") ||
      text.includes("couldn't be found")

    ) {

      conversationStatus = "invalid_domain";

    }

    else {

      conversationStatus = "delivery_failed";

    }

  }

  //----------------------------------------
  // 客户回复
  //----------------------------------------

  else if (isCustomerReply) {

    if (isNewMessage) {

      replyCount++;

      lastReplyContent = snippet;

      lastReplyAt = messageTime;

      if (conversationHistory.trim() !== "") {

        conversationHistory +=
`\n\n-------------------------
${messageTime}
-------------------------
${snippet}`;

      } else {

        conversationHistory = snippet;

      }

    }

    const replyText =
      String(
        lastReplyContent ||
        snippet
      ).toLowerCase();

    //------------------------------------
    // 拒绝合作
    //------------------------------------

    if (

      replyText.includes("not interested") ||
      replyText.includes("no interest") ||
      replyText.includes("unable to assist") ||
      replyText.includes("not our business") ||
      replyText.includes("not part of our current business") ||
      replyText.includes("remove me") ||
      replyText.includes("stop emailing") ||
      replyText.includes("unsubscribe")

    ) {

      conversationStatus = "rejected";

    }

    //------------------------------------
    // 有采购意向
    //------------------------------------

    else if (

      replyText.includes("price") ||
      replyText.includes("catalog") ||
      replyText.includes("quotation") ||
      replyText.includes("quote") ||
      replyText.includes("send details") ||
      replyText.includes("more information") ||
      replyText.includes("minimum order") ||
      replyText.includes("moq") ||
      replyText.includes("sample") ||
      replyText.includes("whatsapp")

    ) {

      conversationStatus = "active";

    }

    //------------------------------------
    // 普通回复
    //------------------------------------

    else {

      conversationStatus = "replied";

    }

  }

  //----------------------------------------
  // 非客户邮件直接跳过
  //----------------------------------------

  else {

    continue;

  }

  //----------------------------------------
  // 输出
  //----------------------------------------

  results.push({

    json: {

      // DataTable 行ID
      id: rowId,

      customer_id: data.customer_id,

      company_name: data.company_name,

      email: customerEmail,

      email_thread_id:
        gmailThreadId,

      email_outreach_status:
        deliveryStatus,

      email_conversation_status:
        conversationStatus,

      email_reply_count:
        replyCount,

      email_last_reply_content:
        lastReplyContent,

      email_last_reply_at:
        lastReplyAt,

      email_last_message_id:
        gmailMessageId,

      email_conversation_history:
        conversationHistory,

      email_failure_reason:
        failureReason,

      updated_at:
        new Date().toISOString()

    }

  });

}

return results;

return $input.all().map(item => {

  const data = item.json;

  const from = data.From || "";
  const subject = data.Subject || "";
  const snippet = data.snippet || "";

  let customer_email = "";

  // =====================================================
  // 判断是否退信
  // =====================================================

  const isBounce =
    subject.toLowerCase().includes("delivery status") ||
    snippet.toLowerCase().includes("address not found") ||
    snippet.toLowerCase().includes("message wasn't delivered") ||
    snippet.toLowerCase().includes("recipient address rejected") ||
    snippet.toLowerCase().includes("user unknown") ||
    snippet.toLowerCase().includes("mailbox unavailable");

  // =====================================================
  // 退信：从 snippet 提取客户邮箱
  // =====================================================

  if (isBounce) {

    const emailRegex =
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;

    const emails =
      snippet.match(emailRegex);

    if (emails && emails.length > 0) {

      // 找第一个不是自己的邮箱、不是 Google 系统邮箱
      customer_email =
        emails.find(e =>
          !e.toLowerCase().includes("google") &&
          !e.toLowerCase().includes("gmail") &&
          !e.toLowerCase().includes("googlemail") &&
          !e.toLowerCase().includes("sender@example.com")
        ) || "";

      customer_email =
        customer_email.toLowerCase().trim();

    }

  }

  // =====================================================
  // 普通邮件：从 From 提取客户邮箱
  // =====================================================

  else {

    const match =
      from.match(/<([^>]+)>/);

    if (match) {

      customer_email =
        match[1].trim().toLowerCase();

    } else {

      const match2 =
        from.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

      if (match2) {

        customer_email =
          match2[0].trim().toLowerCase();

      }

    }

  }

  // =====================================================
  // 输出
  // =====================================================

  return {

    json: {

      // 保留 Gmail 所有原始字段
      ...data,

      // Merge 专用邮箱
      customer_email,

      // Gmail Message ID（永远不要覆盖）
      gmail_message_id: data.id,

      // Gmail Thread ID
      gmail_thread_id: data.threadId,

      // 是否退信（以后业务判断可直接使用）
      is_bounce: isBounce

    }

  };

});
